<?php
declare(strict_types=1);
define('XAR_SPECIAL_FIXTURE_ONLY',true);require __DIR__.'/tactical-special-effects.php';
$deviceDefenseChecks=0;
function deviceDefenseCheck(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);$GLOBALS['deviceDefenseChecks']++;}
function deviceDefenseFixture(string $kind='explosive'):MemoryConnection{
 $db=specialFixture();$initiative=$db->payload('initiative:scene-one');$initiative['active']=false;$db->put('initiative:scene-one',$initiative);
 foreach(['token-player'=>90,'token-monster'=>35,'token-monster-two'=>40,'token-independent'=>95]as$id=>$x){$key='token:scene-one:'.$id;$token=$db->payload($key);$token['x']=$x;$token['y']=in_array($id,['token-monster','token-monster-two'],true)?50:90;$token['layerId']='ground';$token['size']=40;if(in_array($id,['token-monster','token-monster-two'],true)){$token['name']='Garde';$token['hp']=$token['maxHp']=500;}$db->put($key,$token);}
 $store=dsEmpty();$store['devices']=[['id'=>'old-native-device','itemId'=>'old-native-item','abilityId'=>'removed-ability','name'=>'Dispositif déjà posé','creatorCharacterId'=>'removed-character','sourceTokenId'=>'removed-token','controllerAccountId'=>'account-player','sceneId'=>'scene-one','layerId'=>'ground','x'=>30,'y'=>50,'status'=>'active','revision'=>3,'remainingTurns'=>1,'elapsedTurns'=>0,'elapsedTicks'=>0,'mana'=>60,'waitingForConsent'=>false,'mark'=>['x'=>95,'y'=>50],'definition'=>dsDefinition(['kind'=>$kind,'damageFormula'=>'32','damageType'=>'ignore','radiusCells'=>4,'delayTurns'=>1,'widthCells'=>2,'falloffPercent'=>25])]];$db->put('devices',$store);return $db;
}
$db=deviceDefenseFixture();$before=$db->payload('character:character-player');$triggerId='native-device-trigger-0001';$args=['command'=>'scene.advance','arguments'=>['sceneId'=>'scene-one','requestId'=>$triggerId]];$trigger=runCommand($db,'mechanics.command',$args,true);
deviceDefenseCheck($trigger->status===200,'Native clock trigger: '.json_encode($trigger->body));$parent=$db->payload('activity')['pendingAttacks'][0];
deviceDefenseCheck($parent['areaGate']['kind']==='device-damage'&&$parent['areaGate']['deviceDamage']['rolled']['total']==32,'One explosion amount stored');deviceDefenseCheck($db->payload('token:scene-one:token-monster')['hp']===500&&$db->payload('token:scene-one:token-monster-two')['hp']===500,'No damage before MJ');deviceDefenseCheck($db->payload('character:character-player')===$before,'No new casting costs');deviceDefenseCheck($db->payload('devices')['devices'][0]['status']==='spent','The original countdown remains spent');
deviceDefenseCheck((runCommand($db,'mechanics.command',$args,true)->body['deduplicated']??false)===true,'Trigger replay does not reroll');deviceDefenseCheck(count($db->payload('activity')['pendingAttacks'])===1,'Trigger replay queues no duplicate');
$decision=['attackId'=>$parent['id'],'requestId'=>'native-device-decision-0001','confirmed'=>true,'decision'=>'approve','defenseTokenIds'=>['token-monster']];deviceDefenseCheck(runCommand($db,'token.attack.area.resolve',$decision)->status===403,'Only MJ decides');deviceDefenseCheck(in_array(runCommand($db,'token.attack.area.resolve',[...$decision,'defenseTokenIds'=>['foreign']],true)->status,[400,409],true),'Foreign target refused');
$initiative=$db->payload('initiative:scene-one');$initiative['active']=true;$db->put('initiative:scene-one',$initiative);$approved=runCommand($db,'token.attack.area.resolve',$decision,true);deviceDefenseCheck($approved->status===200,'Native resolution: '.json_encode($approved->body));$byId=array_column($approved->body['areaAttacks'],null,'targetTokenId');deviceDefenseCheck($byId['token-monster']['status']==='awaiting-opposition'&&$byId['token-monster-two']['status']==='applied','Each child follows only MJ choice');deviceDefenseCheck($db->payload('token:scene-one:token-monster-two')['hp']===468&&$db->payload('token:scene-one:token-monster')['hp']===500,'Only unopposed child damaged');deviceDefenseCheck($db->payload('character:character-player')===$before,'Creator not cast or charged');
deviceDefenseCheck((runCommand($db,'token.attack.area.resolve',$decision,true)->body['deduplicated']??false)===true&&$db->payload('token:scene-one:token-monster-two')['hp']===468,'Decision replay applies no second damage');
$action=array_values(array_filter($db->payload('activity')['combatActions'],static fn($action)=>in_array('attack:'.$parent['id'],$action['aliases'],true)))[0];deviceDefenseCheck(count($action['actionIds'])>0,'Native history has an undo button');$undone=runCommand($db,'action.undo',['requestId'=>'native-device-undo-0001','actionId'=>$action['actionIds'][0]],true);deviceDefenseCheck($undone->status===200,'Native complete undo: '.json_encode($undone->body));deviceDefenseCheck($db->payload('token:scene-one:token-monster-two')['hp']===500&&$db->payload('devices')['devices'][0]['status']==='active','Undo restores damage and original device state');deviceDefenseCheck($db->payload('character:character-player')===$before,'Undo preserves unrelated caster');
// A spent beam can finish/break after firing: its saved reserve still governs damage.
$db=deviceDefenseFixture('beam');$before=$db->payload('character:character-player');$trigger=runCommand($db,'mechanics.command',['command'=>'scene.advance','arguments'=>['sceneId'=>'scene-one','requestId'=>'native-beam-trigger-0001']],true);deviceDefenseCheck($trigger->status===200,'Native old beam trigger: '.json_encode($trigger->body));$parent=$db->payload('activity')['pendingAttacks'][0];deviceDefenseCheck($db->payload('devices')['devices'][0]['status']==='broken'&&$parent['areaGate']['deviceDamage']['rolled']['total']===60,'Beam finish does not erase fixed amount');deviceDefenseCheck(array_column($parent['areaGate']['deviceDamage']['targets'],'amount')===[60,45],'Beam target falloff stored separately');$initiative=$db->payload('initiative:scene-one');$initiative['active']=true;$db->put('initiative:scene-one',$initiative);$approved=runCommand($db,'token.attack.area.resolve',['attackId'=>$parent['id'],'requestId'=>'native-beam-decision-0001','confirmed'=>true,'decision'=>'approve','defenseTokenIds'=>[]],true);deviceDefenseCheck($approved->status===200,'Native broken beam releases frozen damage: '.json_encode($approved->body));deviceDefenseCheck($db->payload('token:scene-one:token-monster')['hp']===440&&$db->payload('token:scene-one:token-monster-two')['hp']===455,'Beam uses each frozen percentage');deviceDefenseCheck($db->payload('character:character-player')===$before,'Absent creator and contributions remain untouched');
fwrite(STDOUT,json_encode(['ok'=>true,'deviceDefenseChecks'=>$deviceDefenseChecks],JSON_UNESCAPED_UNICODE)."\n");
